// Request sources on access/refresh; failed requests never load a saved feed.
(()=>{const pending=new Set();let epoch=0;
function redraw(){if(typeof route!=='undefined'&&(['home','deals'].includes(route)||(route.startsWith('news/')&&!document.querySelector('#reader-body')))&&!busy)render(route,false);const info=document.querySelector('.feed-status')||document.createElement('span');info.className='feed-status';info.textContent='在线获取 · Steam 公告 / 国区价格';info.title='每次访问请求来源；失败不展示旧快照。';document.querySelector('.rail-foot')?.prepend(info)}
function shuffle(items){const list=[...items];for(let i=list.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[list[i],list[j]]=[list[j],list[i]]}return list}
async function newsSelection(){let owned=[];window.newsRecommendationNote='随机发现：每次刷新重新选游戏；来源没有新公告时不会伪造新新闻。';try{const status=await fetch('/api/core/me',{cache:'no-store'}).then(r=>r.json());if(status.user){const steam=await fetch('/api/core/steam',{cache:'no-store'}).then(r=>r.json());if(steam.bound&&steam.keyConfigured){const response=await fetch('/api/core/steam/library',{cache:'no-store',signal:AbortSignal.timeout(14000)});const data=await response.json();if(!response.ok)throw Error(data.message);owned=data.games||[];window.newsRecommendationNote=owned.length?'来自你的 Steam 游戏库：常玩游戏优先，保留随机探索；均为本次来源返回的公告。':'公开游戏库为空，本次使用随机发现。';}else if(steam.bound)window.newsRecommendationNote='Steam 身份已绑定，但服务器尚缺 Web API Key，本次使用随机发现。';}}catch(e){window.newsRecommendationNote='游戏库本次未能读取，已切换随机发现；可在个人主页查看原因。'}
let top=[];try{const response=await fetch('/api/catalog?mode=top&start=0&request='+Date.now(),{cache:'no-store',signal:AbortSignal.timeout(14000)});const data=await response.json();top=data.items||[]}catch{}const picks=owned.length?[...owned.slice(0,3),...shuffle(owned.slice(3)).slice(0,2),...shuffle(top).slice(0,1)]:shuffle(top).slice(0,6);const explore=shuffle([{appid:570,name:'Dota 2'},{appid:730,name:'Counter-Strike 2'},{appid:230410,name:'Warframe'},{appid:413150,name:'Stardew Valley'}]).slice(0,2);return [...new Map([...picks,...explore].map(g=>[g.appid,g])).values()].slice(0,8);}
async function refresh(kind){if(pending.has(kind))return;pending.add(kind);const requestEpoch=++epoch;SNAPSHOT[kind]=[];SNAPSHOT[kind+'Status']='loading';SNAPSHOT[kind+'At']=null;SNAPSHOT[kind+'Providers']=[];redraw();try{if(location.protocol==='file:')throw Error('请通过在线网站或本地服务访问');const selection=kind==='news'?await newsSelection():[];const names=new Map(selection.map(g=>[g.appid,g.game||g.name]));const extra=selection.length?'&appids='+selection.map(g=>g.appid).join(','):'';const r=await fetch('/api/'+kind+'?request='+Date.now()+'-'+requestEpoch+extra,{cache:'no-store',signal:AbortSignal.timeout(18000),headers:{Accept:'application/json'}});const d=await r.json();SNAPSHOT[kind+'Providers']=Array.isArray(d.providers)?d.providers:[];if(!r.ok||!Array.isArray(d[kind])||d.providers?.length&&d.providers.every(p=>p.status!=='ok'))throw Error('来源暂不可用');SNAPSHOT[kind]=d[kind];if(kind==='news')SNAPSHOT.news=SNAPSHOT.news.map((n,i)=>({...n,game:names.get(n.appid)||n.game,recommendOrder:selection.findIndex(g=>g.appid===n.appid)*100+i}));SNAPSHOT[kind+'At']=d.fetchedAt;SNAPSHOT[kind+'Status']='ready'}catch{SNAPSHOT[kind]=[];SNAPSHOT[kind+'Status']='error'}finally{pending.delete(kind);redraw()}}
document.addEventListener('click',ev=>{const button=ev.target.closest('[data-live-refresh]');if(button){ev.preventDefault();refresh(button.dataset.liveRefresh)}});
function imageCandidates(img){
 const original=img.dataset.originalImage,appid=img.dataset.fallbackAppid,list=[];
 if(original){try{const source=new URL(original);if(/(?:^|\.)steamstatic\.com$/.test(source.hostname)||source.hostname==='shared.st.dl.eccdnx.com'){for(const host of ['shared.cloudflare.steamstatic.com','shared.fastly.steamstatic.com','shared.st.dl.eccdnx.com']){const copy=new URL(source);copy.hostname=host;list.push('/api/media?url='+encodeURIComponent(copy.href));}}list.push(original);}catch{}}
 if(/^[1-9][0-9]{0,8}$/.test(appid||'')){list.push('/api/game-cover?appid='+appid);list.push('/api/media?url='+encodeURIComponent('https://cdn.akamai.steamstatic.com/steam/apps/'+appid+'/header.jpg'));}
 return [...new Set(list)].filter(url=>url!==img.getAttribute('src'));
}
function retryImage(img){img.dataset.retry='0';img.hidden=false;img.parentElement.classList.remove('image-unavailable');img.parentElement.querySelector('.image-retry')?.remove();img.src='/api/media?url='+encodeURIComponent(img.dataset.originalImage);}
document.addEventListener('error',ev=>{
 const img=ev.target;if(!(img instanceof HTMLImageElement)||!img.hasAttribute('data-original-image'))return;
 if(!img._candidates)img._candidates=imageCandidates(img);
 const next=img._candidates.shift();if(next){img.dataset.retry=String(Number(img.dataset.retry||0)+1);img.src=next;return;}
 img.hidden=true;const parent=img.parentElement;parent.classList.add('image-unavailable');const label=parent.querySelector('.image-label');if(label)label.textContent='官方图片暂不可用';
 if(!parent.querySelector('.image-retry')){const button=document.createElement('span');button.className='image-retry';button.role='button';button.tabIndex=0;button.textContent='↻ 重试图片';const retry=e=>{e.preventDefault();e.stopPropagation();img._candidates=null;retryImage(img);};button.onclick=retry;button.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')retry(e);};parent.append(button);}
},true);
document.addEventListener('load',ev=>{const img=ev.target;if(img instanceof HTMLImageElement&&img.hasAttribute('data-original-image')){img.hidden=false;img.parentElement.classList.remove('image-unavailable');}},true);
window.refreshOfflineFeed=()=>Promise.all([refresh('news'),refresh('deals'),refresh('community')]);window.refreshOfflineFeed();})();
